wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::http_client;
use crate::aap::caps::notifier;
use crate::wasi::clocks::wall_clock;

struct Node;

impl Guest for Node {
    fn run(feed_url: String) -> HeartbeatReport {
        let seconds = wall_clock::now().seconds;

        // A transport failure is a value, so a down feed does not fail the
        // heartbeat; it simply counts as zero characters fetched.
        let fetched = match http_client::fetch(&feed_url) {
            Ok(body) => body.chars().count() as u32,
            Err(_) => 0,
        };

        let message = format!("heartbeat t={seconds} fetched={fetched}");
        let notified = notifier::notify(&message);

        // The contract is `ensures notified == true`. Trapping here means no
        // output violating the contract is ever produced.
        if !notified {
            panic!("notifier refused the heartbeat; refusing to emit notified=false");
        }

        HeartbeatReport {
            seconds,
            fetched,
            notified,
        }
    }
}

export!(Node);
